// Host loader for the self-hosted SDEV compiler.
//
// The compiler itself is SDEV: `lang/compiler/driver.sdev` (which pulls in
// `lang/compiler/codegen.sdev` with `use`). The self-hosted compiler compiled
// that program to bytecode once; the result is checked in as
// `driver-artifact.mjs`, generated by `scripts/bake-driver.sdev` — an SDEV
// program — so no JavaScript compiler takes part in building SDEV.
//
// This file contains no compiler logic. It only:
//   1. obtains the seed VM binary (the machine SDEV bytecode runs on),
//   2. loads compiler bytecode + string pool into VM memory,
//   3. answers the compiler's read_file calls: "<stdin>" is the program under
//      compilation, any other path is a module named by `use "path"`,
//   4. decodes the compiler's output stream (`say` values) into bytes.
//
// `compileWith(driver, …)` runs an arbitrary compiler build instead of the
// baked one. The bake/fixed-point gate uses it to prove that the compiler a
// build produces compiles itself to the very same bytes (stage 2 == stage 3).

import { DRIVER_BYTECODE_HEX, DRIVER_POOL_HEX } from './driver-artifact.mjs';
import { applyFmath, writeBlobToMemory, readSliceFromMemory } from './seed-vm.mjs';

const decoder = new TextDecoder();
const encoder = new TextEncoder();

// Node-only module resolution for `use "path"`; absent in the browser.
let nodeFs = null;
async function ensureNodeFs() {
  if (nodeFs) return nodeFs;
  if (typeof process !== 'undefined' && process.versions?.node) {
    nodeFs = (await import(/* @vite-ignore */ 'node:fs')).default;
  }
  return nodeFs;
}

function hexToBytes(hex) {
  const out = new Uint8Array(hex.length >> 1);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
  return out;
}

let cachedModule = null;
let seedLoader = null;

// Hosts can override how the seed VM binary is obtained (the browser
// bridge hands us a fetch-based loader).
export function setSeedLoader(fn) {
  if (seedLoader === fn) return;
  seedLoader = fn;
  cachedModule = null;
}

// The seed binary is a static asset served from `public/wasm/`. It is never
// imported — the browser fetches it by URL, Node reads it off disk at
// runtime — so no bundler ever pulls the binary into a JS chunk.
const SEED_ASSET_PATH = '/wasm/sdev-seed' + '.wasm';

async function defaultSeedBytes() {
  if (typeof process !== 'undefined' && process.versions?.node) {
    const fs = await ensureNodeFs();
    const seedPath = '../../public' + SEED_ASSET_PATH;
    return fs.promises.readFile(new URL(seedPath, import.meta.url));
  }
  const res = await fetch(SEED_ASSET_PATH);
  if (!res.ok) throw new Error(`fetch seed VM: ${res.status}`);
  return new Uint8Array(await res.arrayBuffer());
}

async function seedModule() {
  if (!cachedModule) {
    const wasmBytes = await (seedLoader ? seedLoader() : defaultSeedBytes());
    cachedModule = await WebAssembly.compile(wasmBytes);
  }
  return cachedModule;
}

let baked = null;
/** The checked-in compiler build: `{ bytecode, stringPool }`. */
export function bakedDriver() {
  if (!baked) baked = { bytecode: hexToBytes(DRIVER_BYTECODE_HEX), stringPool: hexToBytes(DRIVER_POOL_HEX) };
  return baked;
}

/**
 * Compile SDEV source with a given compiler build. Returns
 * `{ bytecode, stringPool }` for the seed VM.
 */
export async function compileWith(driver, userSrc, modules = null) {
  await ensureNodeFs();
  const wasmModule = await seedModule();
  const srcBytes = encoder.encode(userSrc);
  const dumped = [];
  let compilerErr = null;
  let mem;
  let allocStr;
  const inst = await WebAssembly.instantiate(wasmModule, {
    env: {
      host_say_i32: (n) => dumped.push(n),
      host_say_str: (ptr, len) => {
        const msg = decoder.decode(readSliceFromMemory(mem, ptr, len));
        compilerErr = compilerErr ? `${compilerErr}\n${msg}` : msg;
      },
      host_say_f64: () => {},
      host_fmath: (op, a, b) => applyFmath(op, a, b),
      host_read_file: (ptr, len) => {
        const path = decoder.decode(readSliceFromMemory(mem, ptr, len));
        let bytes = srcBytes;
        if (path !== '<stdin>') {
          let text = modules && Object.prototype.hasOwnProperty.call(modules, path) ? modules[path] : null;
          if (text == null && nodeFs) {
            try { text = nodeFs.readFileSync(path, 'utf8'); } catch { text = ''; }
          }
          bytes = encoder.encode(text ?? '');
        }
        return writeBlobToMemory(mem, allocStr, bytes);
      },
      host_write_file: () => -1,
      host_http_get: () => 0,
    },
  });
  mem = inst.exports.memory;
  allocStr = inst.exports.alloc_str;
  if (driver.stringPool.length > 0x10000) throw new Error('driver string pool exceeds 64 KiB seed VM limit');
  if (driver.bytecode.length > 0x14000) throw new Error('driver bytecode exceeds 80 KiB seed VM limit');
  new Uint8Array(mem.buffer).set(driver.stringPool, 0);
  const codeBase = inst.exports.code_base();
  new Uint8Array(mem.buffer).set(driver.bytecode, codeBase);
  inst.exports.set_prog_len(driver.bytecode.length);
  inst.exports.run();

  if (compilerErr !== null) {
    throw new Error(compilerErr);
  }
  if (dumped.length === 0) {
    throw new Error('self-hosted compiler exited without emitting bytecode');
  }

  let cursor = 0;
  const bcCount = dumped[cursor++] | 0;
  if (bcCount < 0 || bcCount > 0x14000) throw new Error(`bytecode buffer overflow (${bcCount} bytes, max 81920)`);
  const bytecode = new Uint8Array(bcCount);
  for (let i = 0; i < bcCount; i++) bytecode[i] = dumped[cursor++] & 0xff;
  const poolCount = dumped[cursor++] | 0;
  if (poolCount < 0 || poolCount > 0x10000) throw new Error(`string pool overflow (${poolCount} bytes, max 65536)`);
  const stringPool = new Uint8Array(poolCount);
  for (let i = 0; i < poolCount; i++) stringPool[i] = dumped[cursor++] & 0xff;
  return { bytecode, stringPool };
}

/** Compile SDEV source with the checked-in self-hosted compiler. */
export async function compile(userSrc, modules = null) {
  return compileWith(bakedDriver(), userSrc, modules);
}

export default { compile, compileWith, bakedDriver };
